<template>
 <main class="zj-workspace finance-workspace">
  <header class="zj-heading"><div><div class="zj-eyebrow">众基消防 / 财务管理</div><h1>财务工作台</h1><p>串联合同、项目、报账、账户、收支与开票记录。</p></div><div class="actions"><el-button @click="$router.push('/zhongji/finance/overview')">报账总览</el-button><el-button type="primary" @click="create('invoices')" v-hasPermi="['zhongji:finance:ledger']">登记已开发票</el-button></div></header>
  <section class="finance-metrics"><article v-for="m in metrics" :key="m.label" class="zj-card"><small>{{m.label}}</small><strong>¥ {{money(m.amount)}}</strong></article></section>
  <section class="zj-card"><el-tabs v-model="tab" @tab-change="changeTab"><el-tab-pane v-for="(title,key) in tabs" :key="key" :label="title" :name="key"/></el-tabs>
   <template v-if="tab==='overview'"><div class="finance-overview"><section><h2>资金账户</h2><p class="zj-sub">余额 = 期初余额 + 有效入账 − 有效出账；内部转账不计为经营收支。</p><div class="account-grid"><button v-for="a in summary.accounts||[]" :key="a.id" @click="focus('transactions',{accountId:a.id},a.name)"><small>{{a.name}} {{a.active?'':'（已停用）'}}</small><strong>¥ {{money(a.balance)}}</strong><span>{{a.accountNumber||'未填写账号'}}</span></button></div><el-empty v-if="!summary.accounts?.length" description="还没有资金账户"><el-button @click="create('accounts')" v-hasPermi="['zhongji:finance:ledger']">添加账户</el-button></el-empty></section><section><h2>近12个有流水月份</h2><el-table :data="summary.months||[]"><el-table-column prop="month" label="月份"/><el-table-column label="收入" align="right"><template #default="{row}">{{money(row.income)}}</template></el-table-column><el-table-column label="支出" align="right"><template #default="{row}">{{money(row.expense)}}</template></el-table-column></el-table><p class="zj-sub">报账和开票不自动改变账户余额；只有有效流水计入实际收支。</p></section></div></template>
   <template v-else>
    <div class="zj-filters"><el-input v-model="query.name" clearable :placeholder="tab==='invoices'?'发票号码或客户名称':'名称、编号或用途'" @keyup.enter="search"/><template v-if="['transactions','invoices'].includes(tab)"><el-date-picker v-model="range" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期"/><el-select v-model="query.status" clearable placeholder="全部状态"><el-option :value="tab==='invoices'?'issued':'posted'" label="有效记录"/><el-option value="void" label="已作废"/></el-select></template><el-select v-if="tab==='transactions'" v-model="query.direction" clearable placeholder="全部方向"><el-option v-for="(label,value) in directions" :key="value" :value="value" :label="label"/></el-select><el-button type="primary" @click="search">查询</el-button><el-button @click="reset">清空</el-button><el-button v-if="['accounts','transactions','invoices'].includes(tab)" @click="create(tab)" v-hasPermi="['zhongji:finance:ledger']">{{tab==='accounts'?'添加账户':tab==='invoices'?'登记已开发票':'登记收支 / 转账'}}</el-button></div>
    <el-alert v-if="contextLabel" :title="'关联筛选：'+contextLabel" type="info" closable @close="reset"/><el-alert v-if="error" title="加载失败，请重试" type="error" :closable="false"><el-button link @click="load">重试</el-button></el-alert>
    <el-table v-loading="loading" :data="rows" empty-text="暂无记录" @row-dblclick="detail">
     <template v-if="tab==='contracts'||tab==='projects'"><el-table-column prop="code" label="编号" width="190"/><el-table-column prop="name" label="名称" min-width="240"/><el-table-column v-if="tab==='projects'" prop="contractName" label="合同（空为待签订/待关联）" min-width="220"/><el-table-column v-if="tab==='contracts'" label="合同金额" width="150" align="right"><template #default="{row}">{{row.amount==null?'待确认':money(row.amount)}}</template></el-table-column><el-table-column v-for="c in businessAmounts" :key="c.key" :label="c.label" width="150" align="right"><template #default="{row}">{{money(row[c.key])}}</template></el-table-column><el-table-column :label="tab==='contracts'?'合同未收余额':'待处理报账'" width="160" align="right"><template #default="{row}">{{tab==='contracts'&&row.outstandingAmount==null?'待确认':money(tab==='contracts'?row.outstandingAmount:row.pendingAmount)}}</template></el-table-column></template>
     <template v-else-if="tab==='accounts'"><el-table-column prop="name" label="账户名称" min-width="180"/><el-table-column prop="holder" label="户名" min-width="160"/><el-table-column prop="accountNumber" label="账号 / 标识" min-width="180"/><el-table-column label="期初余额" align="right" width="150"><template #default="{row}">{{money(row.openingBalance)}}</template></el-table-column><el-table-column label="当前余额" align="right" width="160"><template #default="{row}"><strong>{{money(row.balance)}}</strong></template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}">{{row.active?'启用':'停用'}}</template></el-table-column></template>
     <template v-else-if="tab==='invoices'"><el-table-column prop="invoiceDate" label="开票日期" width="125"/><el-table-column prop="invoiceNo" label="发票号码" min-width="210"/><el-table-column prop="buyerName" label="客户 / 购方" min-width="220"/><el-table-column label="价税合计" width="150" align="right"><template #default="{row}">{{money(row.amount)}}</template></el-table-column><el-table-column label="已关联收款" width="150" align="right"><template #default="{row}">{{money(row.receivedAmount)}}</template></el-table-column><el-table-column prop="contractName" label="合同" min-width="200"/><el-table-column prop="projectName" label="项目" min-width="200"/></template>
     <template v-else><el-table-column prop="transactionDate" label="交易日期" width="125"/><el-table-column prop="accountName" label="资金账户" min-width="170"/><el-table-column label="方向" width="105"><template #default="{row}">{{directions[row.direction]}}</template></el-table-column><el-table-column label="金额" width="150" align="right"><template #default="{row}"><strong>{{money(row.amount)}}</strong></template></el-table-column><el-table-column prop="purpose" label="用途" min-width="210"/><el-table-column prop="counterparty" label="交易对方" min-width="160"/><el-table-column prop="contractName" label="合同" min-width="200"/><el-table-column prop="projectName" label="项目" min-width="200"/><el-table-column prop="invoiceNo" label="发票号码" min-width="180"/></template>
     <el-table-column v-if="['transactions','invoices'].includes(tab)" label="状态" width="95"><template #default="{row}"><el-tag :type="row.status==='void'?'info':'success'">{{row.status==='void'?'已作废':'有效'}}</el-tag></template></el-table-column>
     <el-table-column label="操作" width="160" fixed="right"><template #default="{row}"><el-button link type="primary" @click="detail(row)">{{tab==='accounts'?'详情 / 编辑':'详情'}}</el-button><el-button v-if="['contracts','projects','accounts'].includes(tab)" link @click="focus('transactions',{[tab==='contracts'?'contractId':tab==='projects'?'projectId':'accountId']:row.id},row.name)">流水</el-button></template></el-table-column>
    </el-table><el-pagination v-model:current-page="query.pageNum" :page-size="20" :total="total" layout="total,prev,pager,next" @current-change="load"/>
   </template>
  </section>
  <el-drawer v-model="detailsOpen" :title="tabs[detailKind]+'详情'" size="min(780px,96vw)"><template v-if="selected"><h2>{{selected.name||selected.invoiceNo||selected.purpose}}</h2><el-descriptions :column="1" border><el-descriptions-item v-for="[key,label] in detailFields" :key="key" :label="label">{{display(key,selected[key])}}</el-descriptions-item></el-descriptions><template v-if="selected.files"><h3>附件</h3><el-link v-for="(url,i) in selected.files.split(',').filter(Boolean)" :key="url" :href="fileUrl(url)" target="_blank" type="primary" style="display:block;margin:12px 0">预览 / 下载附件 {{i+1}}</el-link></template><div class="drawer-actions"><template v-if="detailKind==='contracts'||detailKind==='projects'"><el-button @click="focus('invoices',{[detailKind==='contracts'?'contractId':'projectId']:selected.id},selected.name);detailsOpen=false">查看开票</el-button><el-button @click="focus('transactions',{[detailKind==='contracts'?'contractId':'projectId']:selected.id},selected.name);detailsOpen=false">查看流水</el-button></template><el-button v-if="detailKind==='accounts'" v-hasPermi="['zhongji:finance:ledger']" @click="editAccount">编辑账户</el-button><el-button v-if="detailKind==='invoices'&&selected.status==='issued'" v-hasPermi="['zhongji:finance:ledger']" type="primary" @click="receiveInvoice">登记收款</el-button><el-button v-if="['transactions','invoices'].includes(detailKind)&&selected.status!=='void'" v-hasPermi="['zhongji:finance:ledger']" type="danger" :loading="saving" @click="cancelRecord">作废记录</el-button></div><p v-if="selected.transferGroup" class="zj-sub">内部转账成对入账；作废会同时撤销转出与转入。</p></template></el-drawer>
  <el-dialog v-model="formOpen" :title="formKind==='accounts'?'资金账户':formKind==='invoices'?'登记已开发票':'登记收支 / 内部转账'" width="min(820px,96vw)" :before-close="closeForm" :close-on-click-modal="false">
   <el-form ref="formRef" :model="draft" label-position="top" :disabled="saving"><div class="ledger-form-grid">
    <template v-if="formKind==='accounts'"><el-form-item label="账户名称" prop="name" :rules="required"><el-input v-model="draft.name" maxlength="120" placeholder="例如：公司账户、现金、备用金"/></el-form-item><el-form-item label="户名"><el-input v-model="draft.holder" maxlength="120"/></el-form-item><el-form-item label="账号 / 自定义标识"><el-input v-model="draft.accountNumber" maxlength="120"/></el-form-item><el-form-item label="期初余额（元）" prop="openingBalance" :rules="required"><el-input v-model="draft.openingBalance" inputmode="decimal"/><small>已有流水后期初余额不可修改。</small></el-form-item><el-form-item label="账户状态"><el-switch v-model="draft.active" active-text="启用" inactive-text="停用"/></el-form-item></template>
    <template v-else>
     <template v-if="formKind==='transactions'"><el-form-item label="交易方向" prop="direction" :rules="required"><el-select v-model="draft.direction" @change="changeDirection"><el-option value="income" label="收入"/><el-option value="expense" label="支出"/><el-option value="transfer" label="内部转账"/></el-select></el-form-item><el-form-item :label="draft.direction==='transfer'?'转出账户':'资金账户'" prop="accountId" :rules="required"><el-select v-model="draft.accountId"><el-option v-for="a in availableAccounts" :key="a.id" :value="a.id" :label="a.name"/></el-select></el-form-item><el-form-item v-if="draft.direction==='transfer'" label="转入账户" prop="toAccountId" :rules="required"><el-select v-model="draft.toAccountId"><el-option v-for="a in availableAccounts.filter(x=>x.id!==draft.accountId)" :key="a.id" :value="a.id" :label="a.name"/></el-select></el-form-item><el-form-item label="交易日期" prop="transactionDate" :rules="required"><el-date-picker v-model="draft.transactionDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="金额（元）" prop="amount" :rules="required"><el-input v-model="draft.amount" inputmode="decimal"/></el-form-item><el-form-item label="交易对方"><el-input v-model="draft.counterparty" maxlength="200"/></el-form-item><el-form-item v-if="draft.direction==='expense'" label="支付报账（可选）"><FinancePicker v-model="draft.reimbursementId" :label="claimLabel" placeholder="选择待处理报账" :loader="name=>ledgerOptions('claims',name)" @select="selectClaim"/></el-form-item><el-form-item v-if="draft.direction==='income'" label="对应开票记录（可选）"><FinancePicker v-model="draft.invoiceId" :label="invoiceLabel" placeholder="选择开票记录" :loader="invoiceChoices" @select="selectInvoice"/></el-form-item></template>
     <template v-else><el-form-item label="发票号码" prop="invoiceNo" :rules="required"><el-input v-model="draft.invoiceNo" maxlength="100"/></el-form-item><el-form-item label="开票日期" prop="invoiceDate" :rules="required"><el-date-picker v-model="draft.invoiceDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="客户 / 购方名称" prop="buyerName" :rules="required"><el-input v-model="draft.buyerName" maxlength="200"/></el-form-item><el-form-item label="购方税号"><el-input v-model="draft.buyerTaxId" maxlength="100"/></el-form-item><el-form-item label="价税合计（元）" prop="amount" :rules="required"><el-input v-model="draft.amount" inputmode="decimal"/></el-form-item><el-form-item label="其中税额（元）"><el-input v-model="draft.taxAmount" inputmode="decimal"/></el-form-item><el-form-item label="发票类型（自定义）"><el-input v-model="draft.invoiceType" maxlength="100" placeholder="例如：增值税普通发票"/></el-form-item></template>
     <template v-if="draft.direction!=='transfer'"><el-form-item label="关联合同（可选）"><FinancePicker v-model="draft.contractId" :label="contractLabel" :disabled="!!draft.invoiceId" placeholder="选择合同" :loader="name=>ledgerOptions('contracts',name)"/></el-form-item><el-form-item label="关联项目（可选）"><FinancePicker v-model="draft.projectId" :label="projectLabel" :disabled="!!draft.invoiceId||!!draft.reimbursementId" placeholder="选择项目" :loader="name=>expenseOptions('projects',name)"/></el-form-item></template>
    </template>
   </div><el-form-item v-if="formKind==='transactions'" label="用途" prop="purpose" :rules="required"><el-input v-model="draft.purpose" type="textarea" maxlength="2000"/></el-form-item><el-form-item v-if="formKind!=='accounts'" label="发票文件 / 交易凭证"><FileUpload v-model="draft.files" :limit="5" :file-size="10" :file-type="['pdf','png','jpg','jpeg']"/></el-form-item><el-form-item label="备注"><el-input v-model="draft.remark" type="textarea" maxlength="2000"/></el-form-item><el-alert v-if="formKind==='invoices'" title="这里登记已经开具的发票及金额，不连接税务开票平台。记录提交后保留原始信息，更正请先作废再重新登记。" type="info" :closable="false"/></el-form>
   <template #footer><el-button :disabled="saving" @click="closeForm(()=>formOpen=false)">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存记录</el-button></template>
  </el-dialog>
 </main>
</template>
<script setup>
import { useFinanceWorkspace } from './composables/useFinanceWorkspace'
import FinancePicker from './components/FinancePicker.vue'
import FileUpload from '@/components/FileUpload/index.vue'
import { fileUrl } from '@/utils/files'
import '@/assets/styles/zhongji.scss'

const {
  tabs, directions, businessAmounts, tab, summary, rows, total, loading, error, query, range, contextLabel,
  detailsOpen, detailKind, selected, formOpen, formKind, formRef, draft, saving,
  claimLabel, invoiceLabel, contractLabel, projectLabel, required, availableAccounts, metrics, detailFields,
  display, load, search, reset, changeTab, focus, detail, create, editAccount, changeDirection, selectClaim,
  invoiceChoices, selectInvoice, receiveInvoice, closeForm, save, cancelRecord, expenseOptions, ledgerOptions, money
} = useFinanceWorkspace()
</script>
<style scoped>.finance-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.finance-metrics small,.finance-metrics strong{display:block}.finance-metrics small{color:#65748b}.finance-metrics strong{font-size:23px;margin-top:12px;overflow-wrap:anywhere}.finance-overview{display:grid;grid-template-columns:1.1fr 1fr;gap:32px}.finance-overview h2{font-size:18px}.account-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.account-grid button{border:1px solid #e5eaf2;background:#f8faff;border-radius:12px;text-align:left;padding:20px;cursor:pointer;color:#17243b}.account-grid strong,.account-grid span{display:block;margin-top:12px}.account-grid strong{font-size:23px}.account-grid span{color:#65748b;font-size:12px}.ledger-form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 20px}.ledger-form-grid :deep(.el-select),.ledger-form-grid :deep(.el-date-editor){width:100%}.ledger-form-grid small{color:#65748b}.actions,.drawer-actions{display:flex;gap:10px;flex-wrap:wrap}.drawer-actions{margin-top:24px}.finance-workspace :deep(.el-descriptions__content){overflow-wrap:anywhere;white-space:pre-wrap}@media(max-width:900px){.finance-metrics{grid-template-columns:1fr 1fr}.finance-overview,.ledger-form-grid{grid-template-columns:1fr}.finance-metrics strong{font-size:19px}.finance-workspace :deep(.el-tabs__item){padding:0 14px}}</style>
